import { componentChain, componentInfo } from "../../source/component-annotate";
import { tplLabel } from "../../source/tpl-annotate";
import { assign } from "./dom";

const TOOLTIP_MAX_W = 420;

function isDisabled(el: Element): boolean {
  try {
    return el.matches(':disabled,[disabled],[aria-disabled="true"]');
  } catch {
    return false;
  }
}

const px = (v: string): number => parseFloat(v) || 0;

/** Raccourci d'une box (padding/margin) : `null` si tout nul, sinon shorthand px. */
function boxValue(t: number, r: number, b: number, l: number): string | null {
  if (!t && !r && !b && !l) return null;
  if (t === r && r === b && b === l) return `${t}px`;
  if (t === b && l === r) return `${t}px ${r}px`;
  return `${t}px ${r}px ${b}px ${l}px`;
}

/** Dimensions de l'élément, arrondies : `120×20`. */
export function dimsText(rect: DOMRect): string {
  return `${Math.round(rect.width)}×${Math.round(rect.height)}`;
}

/** Suffixes communs d'un titre de tooltip : `disabled`, `selected #n`. */
function titleSuffixes(el: Element, selection: Element[]): string[] {
  const parts: string[] = [];
  if (isDisabled(el)) parts.push("disabled");
  const selIdx = selection.indexOf(el);
  if (selIdx >= 0) parts.push(`selected #${selIdx + 1}`);
  return parts;
}

/** Résumé classes pour le tooltip : 3 premières + `(+n)`. Pure. */
export function tooltipClassSummary(el: Element): string {
  const raw = el.getAttribute("class") || "";
  const tokens = raw.trim().length > 0 ? raw.trim().split(/\s+/) : [];
  if (tokens.length === 0) return "";
  const head = tokens.slice(0, 3).map((cls) => `.${cls}`).join("");
  return tokens.length > 3 ? `${head} (+${tokens.length - 3})` : head;
}

/** Titre du tooltip : nom du composant + marqueurs (`· disabled`, `· selected #n`).
 * Les classes/tag + `#id` vivent SOUS le divider (via `tooltipMetrics`). */
export function tooltipTitle(el: Element, selection: Element[]): string {
  const parts: string[] = [];
  // Chaîne React si dispo ; sinon libellé PrestaShop (nom du module / basename .tpl).
  const comp =
    componentChain(el as HTMLElement).join(" > ") ||
    componentInfo(el as HTMLElement)?.component ||
    tplLabel(el);
  if (comp) parts.push(comp);
  parts.push(...titleSuffixes(el, selection));
  return parts.join(" · ");
}

/** Titre alternatif : classes CSS de l'élément (sinon le tag) + suffixes. Pour l'extension. */
export function tooltipClasses(el: Element, selection: Element[]): string {
  const cls = (el.getAttribute("class") || "").trim();
  const head = cls || el.tagName.toLowerCase();
  return [head, ...titleSuffixes(el, selection)].join(" · ");
}

/** Métriques layout en px : classes/tag + `#id` (sous le divider), puis `padding: …` /
 * `gap: …` / `margin: …` (que si non nuls). */
/** Variante pure (pas d'appel `getComputedStyle` propre) — réutilisée par `updateTooltip`
 * qui a déjà calculé `cs` pour `el` (évite un 2e recalcul de style sur la même cible). */
export function tooltipMetricsFromStyle(el: Element, cs: CSSStyleDeclaration): string {
  const lines: string[] = [];
  const cls = tooltipClassSummary(el);
  if (cls) lines.push(cls + (el.id ? ` · #${el.id}` : ""));
  else if (el.id) lines.push(`#${el.id}`);

  const padding = boxValue(
    px(cs.paddingTop),
    px(cs.paddingRight),
    px(cs.paddingBottom),
    px(cs.paddingLeft),
  );
  if (padding) lines.push(`padding: ${padding}`);

  const rowGap = px(cs.rowGap);
  const colGap = px(cs.columnGap);
  if (/flex|grid/.test(cs.display) && (rowGap || colGap)) {
    lines.push(`gap: ${rowGap === colGap ? `${rowGap}px` : `${rowGap}px ${colGap}px`}`);
  }

  const margin = boxValue(
    px(cs.marginTop),
    px(cs.marginRight),
    px(cs.marginBottom),
    px(cs.marginLeft),
  );
  if (margin) lines.push(`margin: ${margin}`);

  return lines.join("\n");
}

/** `tooltipMetricsFromStyle` + son propre `getComputedStyle` — pour un appel autonome
 * (tests, appelants qui n'ont pas déjà `cs` sous la main). */
export function tooltipMetrics(el: Element): string {
  return tooltipMetricsFromStyle(el, getComputedStyle(el));
}

export function updateTooltip(
  tooltip: HTMLElement,
  label: HTMLElement,
  divider: HTMLElement,
  metrics: HTMLElement,
  dims: HTMLElement,
  el: Element,
  selection: Element[],
  rect: DOMRect,
  cs: CSSStyleDeclaration,
  titleOf: (el: Element, selection: Element[]) => string = tooltipTitle,
): void {
  const title = titleOf(el, selection);
  const metricsText = tooltipMetricsFromStyle(el, cs);
  label.textContent = title;
  label.style.display = title ? "block" : "none";
  metrics.textContent = metricsText;
  metrics.style.display = metricsText ? "block" : "none";
  // Barre horizontale entre composant et métriques (si les deux présents).
  divider.style.display = title && metricsText ? "block" : "none";
  dims.textContent = dimsText(rect);
  tooltip.style.display = "flex";

  const tipH = tooltip.offsetHeight;
  let top = rect.bottom + 8;
  if (top + tipH > window.innerHeight) top = rect.top - tipH - 8;
  let left = rect.left;
  if (left + TOOLTIP_MAX_W > window.innerWidth) {
    left = window.innerWidth - TOOLTIP_MAX_W - 10;
  }
  if (left < 4) left = 4;
  assign(tooltip, { top: `${top}px`, left: `${left}px` });
}
