import {
  DEFAULT_SETTINGS,
  gestureMatches,
  keyMatches,
  type ClickTrigger,
} from "../settings";
import { isTreeSelectMode, requestContextMenu, requestSelect } from "../devpanel/inspected";
import { elementText } from "../format";
import type { InspectorCallbacks, PickResult } from "../types";
import { DOWN_TYPE, CONTEXT_MENU_OPEN, IGNORE_ATTR, PICKER_ARMED, PRESS_EVENTS, SWALLOW_MS } from "./constants/behavior";
import { createKeyCommandMatcher } from "./key-command";
import { PICKING_CSS } from "./constants/picker";
import { getCssSelector } from "./css-selector";
import { containsPoint, resolveTarget, shouldIgnore } from "./hit-test";
import { createSurfaces, type Surfaces } from "./surfaces/create";
import { clearDecorations, renderDecorations } from "./surfaces/decorations";
import { renderMarkers } from "./surfaces/markers";
import { hideHover, positionOverlay } from "./surfaces/overlay";
import { updateTooltip } from "./surfaces/tooltip";
import { getXPath } from "./xpath";

/**
 * Inspecteur DOM impératif, sans React. Survol → overlay + tooltip ; clic →
 * pick ; Maj+clic → accumulation ; Entrée → confirme ; Échap → annule. Produit
 * un `PickResult` partiel (route/xpath/css/tagName/id) — l'enrichissement React
 * (`reactComponent`/`reactSource`) se fait côté appelant via `enrichResult`.
 *
 * `activate()` installe tout, `deactivate()` démonte tout (règle : tout init a
 * son cleanup). No-op en SSR. Orchestration uniquement : le hit-test vit dans
 * `hit-test.ts`, les surfaces DOM dans `surfaces/`.
 */
class Inspector {
  private active = false;
  private styleEl: HTMLStyleElement | null = null;
  private surfaces: Surfaces | null = null;
  private lastTarget: Element | null = null;
  private selection: Element[] = [];
  private observer: ResizeObserver | null = null;
  private hovering = false;
  /**
   * Dernier rect affiché par l'overlay. `refreshHover` ne repositionne que s'il a
   * bougé : la notification initiale d'un `ResizeObserver` (à chaque `observe()`
   * d'une nouvelle cible) couperait sinon la glisse en cours.
   */
  private hoverRect: Pick<DOMRect, "top" | "left" | "width" | "height"> | null = null;
  /** rAF en attente du repositionnement du survol (scroll/resize coalescés par frame). */
  private frame = 0;
  /** rAF en attente du traitement mousemove (coalescé par frame, indépendant de `frame`
   * ci-dessus — déclenchement différent, peuvent être en vol simultanément). */
  private moveFrame = 0;
  /** Dernière position mousemove reçue, traitée une fois par frame. */
  private pendingMove: { x: number; y: number } | null = null;
  /** Mode recherche actif : pas de rect de survol (les rects de recherche prennent le relais). */
  private searchMode = false;
  /** Matcher de la commande clavier « inspect » (modificateur + touche, simple/double-tap). */
  private inspectMatcher = createKeyCommandMatcher();

  constructor(private readonly callbacks: InspectorCallbacks) {}

  private get multi(): boolean {
    return (
      this.callbacks.multi !== false &&
      typeof this.callbacks.onPickMany === "function"
    );
  }

  activate(): void {
    if (this.active || typeof document === "undefined") return;
    this.active = true;
    PICKER_ARMED.value = true;

    this.styleEl = document.createElement("style");
    this.styleEl.setAttribute(IGNORE_ATTR, "");
    this.styleEl.textContent = PICKING_CSS;
    document.head.appendChild(this.styleEl);

    this.surfaces = createSurfaces();
    document.body.appendChild(this.surfaces.container);
    document.body.style.cursor = "crosshair";

    window.addEventListener("mousemove", this.onMouseMove, true);
    for (const type of PRESS_EVENTS) {
      window.addEventListener(type, this.onPress, true);
    }
    window.addEventListener("keydown", this.onKeyDown, true);
    window.addEventListener("scroll", this.onViewportChange, true);
    window.addEventListener("resize", this.onViewportChange);
    window.addEventListener("transitionend", this.refreshAll, true);
    window.addEventListener("animationend", this.refreshAll, true);

    if (typeof ResizeObserver !== "undefined") {
      this.observer = new ResizeObserver(() => this.onViewportChange());
    }
  }

  deactivate(): void {
    if (!this.active) return;
    this.active = false;
    PICKER_ARMED.value = false;
    this.lastTarget = null;
    this.hoverRect = null;
    this.selection = [];
    this.inspectMatcher.reset();
    if (typeof document !== "undefined") document.body.style.cursor = "";

    window.removeEventListener("mousemove", this.onMouseMove, true);
    for (const type of PRESS_EVENTS) {
      window.removeEventListener(type, this.onPress, true);
    }
    window.removeEventListener("keydown", this.onKeyDown, true);
    window.removeEventListener("scroll", this.onViewportChange, true);
    window.removeEventListener("resize", this.onViewportChange);
    window.removeEventListener("transitionend", this.refreshAll, true);
    window.removeEventListener("animationend", this.refreshAll, true);

    if (this.frame && typeof cancelAnimationFrame === "function") {
      cancelAnimationFrame(this.frame);
    }
    this.frame = 0;
    if (this.moveFrame && typeof cancelAnimationFrame === "function") {
      cancelAnimationFrame(this.moveFrame);
    }
    this.moveFrame = 0;
    this.pendingMove = null;
    this.observer?.disconnect();
    this.observer = null;
    this.styleEl?.remove();
    this.surfaces?.container.remove();
    this.styleEl = null;
    this.surfaces = null;
  }

  // --- Rendu (délègue à surfaces) ------------------------------------------

  private hideHover(): void {
    this.hovering = false;
    this.hoverRect = null;
    if (!this.surfaces) return;
    hideHover(this.surfaces.overlay, this.surfaces.tooltip);
    clearDecorations(this.surfaces.decorLayer);
  }

  private showHover(el: Element, rect: DOMRect, animate = true): void {
    if (!this.surfaces) return;
    positionOverlay(this.surfaces.overlay, rect, animate);
    // Un seul `getComputedStyle(el)` partagé entre tooltip et décorations (padding/gap/
    // margin) plutôt que chacune le recalcule pour la même cible.
    const cs = getComputedStyle(el);
    updateTooltip(
      this.surfaces.tooltip,
      this.surfaces.tooltipLabel,
      this.surfaces.tooltipDivider,
      this.surfaces.tooltipMetrics,
      this.surfaces.dims,
      el,
      this.selection,
      rect,
      cs,
      this.callbacks.getTitle,
    );
    this.renderDecor(el, rect, cs);
    this.hovering = true;
    this.hoverRect = { top: rect.top, left: rect.left, width: rect.width, height: rect.height };
  }

  /** Dessine (ou efface) les décorations layout selon `getOverlays`. `cs` : réutilisé s'il
   * vient d'être calculé par l'appelant (`showHover`), sinon recalculé (`refreshDecorations`,
   * toggle sans survol). */
  private renderDecor(el: Element, rect: DOMRect, cs?: CSSStyleDeclaration): void {
    if (!this.surfaces) return;
    const overlays = this.callbacks.getOverlays?.();
    if (overlays && (overlays.padding || overlays.gap || overlays.margin)) {
      renderDecorations(this.surfaces.decorLayer, el, rect, overlays, cs ?? getComputedStyle(el));
    } else {
      clearDecorations(this.surfaces.decorLayer);
    }
  }

  /** Re-render des décorations sur l'élément survolé (toggle sans mousemove). */
  refreshDecorations(): void {
    if (!this.active || !this.surfaces) return;
    if (this.lastTarget && this.lastTarget.isConnected) {
      this.renderDecor(this.lastTarget, this.lastTarget.getBoundingClientRect());
    } else {
      clearDecorations(this.surfaces.decorLayer);
    }
  }

  private renderSelection(): void {
    if (this.surfaces) renderMarkers(this.surfaces.markerLayer, this.selection);
  }

  private pickTargetAt(x: number, y: number): Element | null {
    if (
      this.lastTarget &&
      this.lastTarget.isConnected &&
      containsPoint(this.lastTarget, x, y)
    ) {
      return this.lastTarget;
    }
    return resolveTarget(x, y);
  }

  private syncObserver(): void {
    if (!this.observer) return;
    this.observer.disconnect();
    const seen = new Set<Element>();
    const watch = (el: Element | null) => {
      if (el && el.isConnected && !seen.has(el)) {
        seen.add(el);
        this.observer!.observe(el);
      }
    };
    watch(this.lastTarget);
    for (const el of this.selection) watch(el);
  }

  // --- Mutations de sélection ----------------------------------------------

  private afterSelectionChange(): void {
    this.syncObserver();
    this.renderSelection();
    this.callbacks.onSelectionChange?.(this.selection.length);
    if (this.lastTarget && this.lastTarget.isConnected) {
      this.showHover(
        this.lastTarget,
        this.lastTarget.getBoundingClientRect(),
        false,
      );
    }
  }

  private toggleSelection(el: Element): void {
    const idx = this.selection.indexOf(el);
    if (idx >= 0) this.selection.splice(idx, 1);
    else this.selection.push(el);
    this.afterSelectionChange();
  }

  // --- Résultat -------------------------------------------------------------

  private buildResult(el: Element): PickResult {
    return {
      route: this.callbacks.getRoute(),
      xpath: getXPath(el),
      cssSelector: getCssSelector(el),
      text: elementText(el),
      tagName: el.tagName.toLowerCase(),
      id: el.id || null,
      reactComponent: null,
      reactSource: null,
    };
  }

  private finishMulti(): void {
    const results = this.selection
      .filter((el) => el.isConnected)
      .map((el) => this.buildResult(el));
    this.deactivate();
    this.callbacks.onPickMany?.(results);
  }

  /** Avale les events résiduels (pointerup/click) après un pick consommé. */
  private swallowTrailingPress(): void {
    const swallow = (e: Event) => {
      e.preventDefault();
      e.stopPropagation();
      e.stopImmediatePropagation();
    };
    const cleanup = () => {
      for (const type of PRESS_EVENTS) {
        window.removeEventListener(type, swallow, true);
      }
      window.removeEventListener("click", cleanup, true);
    };
    for (const type of PRESS_EVENTS) {
      window.addEventListener(type, swallow, true);
    }
    window.addEventListener("click", cleanup, true);
    setTimeout(cleanup, SWALLOW_MS);
  }

  // --- Handlers (arrow = identité stable pour add/remove) -------------------

  /** Active/désactive le mode recherche : fige le rect de survol de l'inspecteur. */
  setSearchMode(on: boolean): void {
    this.searchMode = on;
    if (on) this.hideHover();
  }

  /** Coalesce le traitement mousemove à une fois par frame (jusqu'à 60-120 events/s
   * natifs sinon, chacun forçant un hit-test complet — voir `processMouseMove`). */
  private onMouseMove = (e: MouseEvent): void => {
    this.pendingMove = { x: e.clientX, y: e.clientY };
    if (typeof requestAnimationFrame !== "function") {
      this.processMouseMove();
      return;
    }
    if (this.moveFrame) return;
    this.moveFrame = requestAnimationFrame(() => {
      this.moveFrame = 0;
      this.processMouseMove();
    });
  };

  private processMouseMove(): void {
    const pending = this.pendingMove;
    if (!pending) return;
    const { x, y } = pending;
    if (this.searchMode) {
      this.lastTarget = null;
      this.hideHover();
      return;
    }
    // Menu contextuel ouvert : survol figé sur l'élément du menu (le curseur
    // peut aller sur le menu sans perdre le rect ; le scroll le recolle).
    if (CONTEXT_MENU_OPEN.value) return;
    // Fast-path : le curseur reste très majoritairement SUR le même élément entre deux
    // frames (micro-mouvements) — réutiliser `lastTarget` sans relancer le hit-test complet
    // (`resolveTarget` : descente pointer-events:none avec getComputedStyle par enfant,
    // coûteux). `document.elementFromPoint` seul (pas `containsPoint`/bounding rect) :
    // un gros conteneur (ex. panneau de mega-menu, 1600px de large, dizaines de liens
    // imbriqués) a un bounding rect qui engloberait aussi tous ses enfants — `containsPoint`
    // y restait "vrai" en permanence dès que `lastTarget` devenait ce conteneur, empêchant
    // de jamais redescendre survoler un lien interne (régression constatée en usage réel).
    // `elementFromPoint` reflète le VRAI élément le plus profond sous le curseur, pas juste
    // son rectangle englobant — un seul appel natif, toujours moins cher que `resolveTarget`.
    const target =
      this.lastTarget && this.lastTarget.isConnected && document.elementFromPoint(x, y) === this.lastTarget
        ? this.lastTarget
        : resolveTarget(x, y);
    if (!target || shouldIgnore(target)) {
      this.lastTarget = null;
      this.hideHover();
      return;
    }
    if (target === this.lastTarget) return;
    this.lastTarget = target;
    this.callbacks.onHover?.(target);
    const rect = target.getBoundingClientRect();
    if (rect.width === 0 && rect.height === 0) {
      this.hideHover();
    } else {
      // Instantané à la (ré)apparition, glisse tant que le survol continue.
      this.showHover(target, rect, this.hovering);
    }
    // Observé APRÈS l'affichage : la notification initiale du ResizeObserver
    // retrouve le rect mémorisé (`hoverRect`) → no-op, la glisse continue.
    this.syncObserver();
  }

  private commands(): typeof DEFAULT_SETTINGS.commands {
    return this.callbacks.getCommands?.() ?? DEFAULT_SETTINGS.commands;
  }

  /** Type de clic de cet event (ou `null` : avalé mais sans action). */
  private kindOf(e: Event, me: MouseEvent): ClickTrigger | null {
    if (e.type === DOWN_TYPE && me.button === 0) return "click";
    // Clic droit sur l'événement `contextmenu` : `onPress` l'avale (preventDefault)
    // avant d'ouvrir notre menu → le menu natif du navigateur est supprimé.
    if (e.type === "contextmenu") return "rightclick";
    if (e.type === "dblclick") return "dblclick";
    return null;
  }

  private onPress = (e: Event): void => {
    // Mode recherche exclusif : les gestes de picking sont désactivés ; un clic
    // hors de l'UI de recherche la fermera (handler doc-level du popover).
    if (this.searchMode) return;
    // Menu contextuel ouvert : ce geste ne fait que le fermer — pas de pick
    // (le prochain clic, menu fermé, pickera normalement).
    if (CONTEXT_MENU_OPEN.value) return;
    const me = e as MouseEvent;
    if (shouldIgnore(e.target as Element | null)) return;

    const target = this.pickTargetAt(me.clientX, me.clientY);
    if (!target) return;

    e.preventDefault();
    e.stopPropagation();
    e.stopImmediatePropagation();

    const kind = this.kindOf(e, me);
    if (!kind) return;

    const cmds = this.commands();
    const isMulti = this.multi && gestureMatches(cmds.multi, me, kind);
    const isCopyHtml = gestureMatches(cmds.copyHtml, me, kind);
    // Config par défaut (`copy: { modifier: "none", trigger: "click" }`) : ignore les
    // modificateurs incidents (Ctrl/Alt/Meta) plutôt que d'exiger STRICTEMENT aucun
    // modificateur — Ctrl/Alt sont réservés aux raccourcis "picker désarmé"
    // (`commands.source`/`commands.usage`, voir `click-to-source.ts`), pas pertinents une
    // fois le picker armé : un clic gauche doit picker, point. Un remappage explicite de
    // `copy` (modifier/trigger différents du défaut) reste respecté à la lettre.
    const isCopy =
      cmds.copy.modifier === "none" && cmds.copy.trigger === "click"
        ? kind === "click" && !isMulti && !isCopyHtml
        : gestureMatches(cmds.copy, me, kind);

    // Geste « multi » démarre la sélection ; ensuite le geste « copier » continue
    // d'ajouter / retirer (accumulation). Le geste « valider » (clavier) confirme.
    if (this.multi && (isMulti || (this.selection.length > 0 && isCopy))) {
      this.toggleSelection(target);
      return;
    }

    if (isCopy) {
      // Mode HTML (arbre monté) : clic → sélectionne l'élément dans l'arbre (pas de copie).
      if (isTreeSelectMode()) {
        this.swallowTrailingPress();
        requestSelect(target);
        return;
      }
      const result = this.buildResult(target);
      this.deactivate();
      this.swallowTrailingPress();
      this.callbacks.onPick(result);
      return;
    }

    // Menu contextuel (clic droit par défaut) — l'inspecteur reste armé.
    if (isCopyHtml) {
      // Mode HTML : clic droit page → menu de l'arbre (3 options, tout élément, svg inclus).
      if (isTreeSelectMode()) {
        requestContextMenu(target, me.clientX, me.clientY);
        return;
      }
      // Le rect figé pendant le menu doit être sur l'élément du menu.
      if (target !== this.lastTarget) {
        this.lastTarget = target;
        this.showHover(target, target.getBoundingClientRect(), false);
        this.syncObserver();
      }
      this.callbacks.onContextMenu?.(target, { x: me.clientX, y: me.clientY });
    }
  };

  private onKeyDown = (e: KeyboardEvent): void => {
    const cmds = this.commands();

    // Commande « inspect » (modificateur + touche, simple ou double-tap) → ouvre le
    // panneau pour l'élément survolé ET reste armé : le survol continue de piloter
    // l'arbre HTML (on descend dans les divs enfants). Échap désarme. (La commande
    // « search » est gérée globalement par le hook, pour marcher même picker non armé.)
    const inspectStatus = this.callbacks.onInspect
      ? this.inspectMatcher.status(e, cmds.inspect)
      : null;
    if (inspectStatus === "wait") {
      e.preventDefault();
      e.stopPropagation();
      return;
    }
    if (
      inspectStatus === "fire" &&
      this.callbacks.onInspect &&
      this.lastTarget &&
      this.lastTarget.isConnected
    ) {
      e.preventDefault();
      e.stopPropagation();
      this.callbacks.onInspect(this.lastTarget);
      return;
    }

    if (keyMatches(cmds.confirm, e.key) && this.multi && this.selection.length > 0) {
      e.preventDefault();
      e.stopPropagation();
      this.finishMulti();
      return;
    }
    if (keyMatches(cmds.cancel, e.key)) {
      e.preventDefault();
      e.stopPropagation();
      this.deactivate();
      this.callbacks.onCancel();
    }
  };

  /** Snapshot de la sélection multiple (Maj+clics). */
  getSelection(): Element[] {
    return [...this.selection];
  }

  // Ne touche QUE les markers de sélection : les `transitionend`/`animationend`
  // d'une page animée réinitialiseraient en boucle la transition de l'overlay
  // → pas de glisse. Le survol suit scroll/resize via `onViewportChange`.
  private refreshAll = (): void => {
    if (!this.active) return;
    this.renderSelection();
  };

  /** Scroll (fenêtre ou sous-conteneur, capture) / resize : markers + survol recollé à l'élément. */
  private onViewportChange = (): void => {
    if (!this.active) return;
    this.refreshAll();
    this.scheduleHover();
  };

  /** Coalesce les repositionnements du survol à une fois par frame. */
  private scheduleHover(): void {
    if (typeof requestAnimationFrame !== "function") {
      this.refreshHover();
      return;
    }
    if (this.frame) return;
    this.frame = requestAnimationFrame(() => {
      this.frame = 0;
      this.refreshHover();
    });
  }

  /** Repositionne instantanément (sans glisse) le survol sur `lastTarget`. */
  private refreshHover(): void {
    if (!this.active || !this.hovering || this.searchMode || !this.lastTarget) return;
    if (!this.lastTarget.isConnected) {
      this.lastTarget = null;
      this.hideHover();
      return;
    }
    const rect = this.lastTarget.getBoundingClientRect();
    if (rect.width === 0 && rect.height === 0) {
      this.hideHover();
      return;
    }
    const prev = this.hoverRect;
    if (
      prev &&
      prev.top === rect.top &&
      prev.left === rect.left &&
      prev.width === rect.width &&
      prev.height === rect.height
    ) {
      // Rien n'a bougé (ex. notification initiale du ResizeObserver) : ne pas
      // toucher l'overlay, sinon la glisse en cours est coupée.
      return;
    }
    this.showHover(this.lastTarget, rect, false);
  }
}

export function createInspector(callbacks: InspectorCallbacks): {
  activate: () => void;
  deactivate: () => void;
  refreshDecorations: () => void;
  setSearchMode: (on: boolean) => void;
  /** Sélection multiple courante (Maj+clics), snapshot. */
  getSelection: () => Element[];
} {
  const inspector = new Inspector(callbacks);
  return {
    activate: () => inspector.activate(),
    deactivate: () => inspector.deactivate(),
    refreshDecorations: () => inspector.refreshDecorations(),
    setSearchMode: (on) => inspector.setSearchMode(on),
    getSelection: () => inspector.getSelection(),
  };
}
